import{c as e,Q as r,j as a,m as d}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"系统性能","description":"","frontmatter":{"title":"系统性能"},"headers":[],"relativePath":"综合知识/系统工程/系统性能.md","filePath":"综合知识/系统工程/系统性能.md","lastUpdated":null}'),n={name:"综合知识/系统工程/系统性能.md"};function o(s,t,l,h,i,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h3 id="系统性能评价" tabindex="-1">系统性能评价 <a class="header-anchor" href="#系统性能评价" aria-label="Permalink to &quot;系统性能评价&quot;">​</a></h3><h4 id="评价程序准确度排序" tabindex="-1">评价程序准确度排序 <a class="header-anchor" href="#评价程序准确度排序" aria-label="Permalink to &quot;评价程序准确度排序&quot;">​</a></h4><blockquote><p>四种评价程序，从高→低准确度：<strong>真实程序 &gt; 核心程序 &gt; 小型基准程序 &gt; 合成基准程序</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">评价程序</th><th style="text-align:center;">准确度</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>真实程序</strong></td><td style="text-align:center;">最高</td><td>实际运行的应用程序</td></tr><tr><td style="text-align:center;"><strong>核心程序</strong></td><td style="text-align:center;">高</td><td>应用程序中使用最频繁的核心部分</td></tr><tr><td style="text-align:center;">小型基准程序</td><td style="text-align:center;">中</td><td>简化的小型测试程序</td></tr><tr><td style="text-align:center;"><strong>合成基准程序</strong></td><td style="text-align:center;">最低</td><td>人工合成的测试程序</td></tr></tbody></table><blockquote><p><strong>基准测试程序（Benchmark）</strong>：将应用程序中用得最多、最频繁的核心程序作为评价计算机性能的标准程序。</p></blockquote><hr><h3 id="tpc-基准" tabindex="-1">TPC 基准 <a class="header-anchor" href="#tpc-基准" aria-label="Permalink to &quot;TPC 基准&quot;">​</a></h3><blockquote><p>TPC（Transaction Processing Performance Council）是制定商务应用基准程序标准规范的非营利组织。</p></blockquote><table tabindex="0"><thead><tr><th>TPC 基准</th><th>对应场景</th></tr></thead><tbody><tr><td><strong>TPC-C</strong></td><td><strong>在线事务处理（OLTP）</strong></td></tr><tr><td>TPC-H</td><td>决策支持/即席查询</td></tr><tr><td>TPC-E</td><td>企业信息服务型 OLTP</td></tr></tbody></table><hr><h3 id="web-服务器性能指标" tabindex="-1">Web 服务器性能指标 <a class="header-anchor" href="#web-服务器性能指标" aria-label="Permalink to &quot;Web 服务器性能指标&quot;">​</a></h3><p><strong>主要指标：</strong></p><table tabindex="0"><thead><tr><th>包含</th><th>不包含</th></tr></thead><tbody><tr><td>最大并发连接数</td><td><s>丢包率</s></td></tr><tr><td>响应延迟</td><td></td></tr><tr><td>吞吐量</td><td></td></tr></tbody></table><p><strong>评测方法</strong>：基准性能测试、压力测试、<strong>可靠性测试</strong>。</p><hr><h3 id="系统调整参数" tabindex="-1">系统调整参数 <a class="header-anchor" href="#系统调整参数" aria-label="Permalink to &quot;系统调整参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统类型</th><th>主要调整参数</th></tr></thead><tbody><tr><td><strong>数据库系统</strong></td><td>CPU/内存使用状况、<strong>查询语句性能</strong>、进程/线程使用状态、日志文件大小</td></tr><tr><td><strong>应用系统</strong></td><td>可用性、响应时间、<strong>并发用户数</strong>、特定应用资源占用</td></tr></tbody></table>',17)])])}const p=e(n,[["render",o]]);export{b as __pageData,p as default};
